ALTER TABLE public.work_stages ADD COLUMN removed boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.capture_schedule_version(_work_id uuid,_reason text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v integer; snapshot jsonb; BEGIN PERFORM id FROM public.work_registry WHERE id=_work_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Obra não encontrada.'; END IF; SELECT coalesce(max(version),0)+1 INTO v FROM public.work_schedule_versions WHERE work_id=_work_id; SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'sort',s.sort,'planned_start',s.planned_start,'planned_end',s.planned_end,'responsible',s.responsible,'observations',s.observations,'scope_services',s.scope_services,'weight',s.weight,'dependency_id',s.dependency_id) ORDER BY s.sort,s.id),'[]') INTO snapshot FROM public.work_stages s WHERE s.work_id=_work_id AND NOT s.removed; INSERT INTO public.work_schedule_versions(work_id,version,stages,notes,reason) SELECT _work_id,v,snapshot,schedule_notes,_reason FROM public.work_registry WHERE id=_work_id; RETURN v; END $$;
CREATE FUNCTION public.remove_schedule_stage(_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.work_stages; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO s FROM public.work_stages WHERE id=_id FOR UPDATE; IF NOT FOUND OR s.removed THEN RAISE EXCEPTION 'Etapa não encontrada.'; END IF; PERFORM id FROM public.work_registry WHERE id=s.work_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.work_records WHERE stage_id=s.id) OR EXISTS(SELECT 1 FROM public.financial_entries WHERE stage_id=s.id) OR EXISTS(SELECT 1 FROM public.work_stages WHERE dependency_id=s.id AND NOT removed) THEN RAISE EXCEPTION 'Esta etapa possui registros ou dependências. Preserve-a ou remova os vínculos antes de excluir.'; END IF; IF EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=s.work_id) AND nullif(trim(_reason),'') IS NULL THEN RAISE EXCEPTION 'Informe o motivo da exclusão.'; END IF; UPDATE public.work_stages SET removed=true,schedule_change_reason=_reason WHERE id=s.id; IF EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=s.work_id) THEN PERFORM public.capture_schedule_version(s.work_id,_reason); END IF; END $$;
REVOKE ALL ON FUNCTION public.remove_schedule_stage(uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.remove_schedule_stage(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.reorder_work_schedule(_work_id uuid,_ids uuid[],_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM id FROM public.work_registry WHERE id=_work_id FOR UPDATE; SELECT count(*) INTO n FROM public.work_stages WHERE work_id=_work_id AND NOT removed; IF cardinality(_ids)<>n OR (SELECT count(DISTINCT x) FROM unnest(_ids) x)<>n OR EXISTS(SELECT 1 FROM unnest(_ids) x WHERE NOT EXISTS(SELECT 1 FROM public.work_stages WHERE work_id=_work_id AND id=x AND NOT removed)) THEN RAISE EXCEPTION 'Ordem inválida.'; END IF; IF EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=_work_id) AND nullif(trim(_reason),'') IS NULL THEN RAISE EXCEPTION 'Informe o motivo da reprogramação.'; END IF; PERFORM set_config('jmg.schedule_batch','on',true); UPDATE public.work_stages s SET sort=u.ordinality-1,schedule_change_reason=_reason FROM unnest(_ids) WITH ORDINALITY AS u(id,ordinality) WHERE s.id=u.id AND s.work_id=_work_id; PERFORM set_config('jmg.schedule_batch','off',true); IF EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=_work_id) THEN PERFORM public.capture_schedule_version(_work_id,_reason); END IF; END $$;
CREATE FUNCTION public.guard_removed_stage() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.removed IS DISTINCT FROM old.removed AND coalesce(current_setting('jmg.stage_remove',true),'')<>'on' THEN RAISE EXCEPTION 'Use a operação Excluir etapa.'; END IF; IF old.removed AND NOT new.removed THEN RAISE EXCEPTION 'Etapa excluída não pode ser reativada.'; END IF; RETURN new; END $$;
COMMENT ON COLUMN public.work_stages.removed IS 'Soft deletion preserves stage identity and audit; operational readers exclude removed stages.';